@page "/apply"
@using sv_feaa0fe75bf642d5a897e2dadda3a343.Components.Application
@using sv_feaa0fe75bf642d5a897e2dadda3a343.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (_submitted)
    {
        <div class="alert alert-success text-center">
            <h4>Application Submitted Successfully!</h4>
            <p class="mb-0">Your application ID is: <strong>@_applicationId</strong></p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="_currentStep" OnNavigate="NavigateToStep" />

        @if (!string.IsNullOrEmpty(_errorMessage))
        {
            <div class="alert alert-danger">@_errorMessage</div>
        }

        @switch (_currentStep)
        {
            case 0:
                @RenderPersonalInfo()
                break;
            case 1:
                @RenderWorkHistory()
                break;
            case 2:
                @RenderReferences()
                break;
            case 3:
                @RenderCoverLetter()
                break;
            case 4:
                @RenderReview()
                break;
        }
    }
</div>

@* Step 1: Personal Info *@
@{ RenderFragment RenderPersonalInfo() => @<div>
    <h4>Personal Information</h4>
