@code {
    private int _currentStep;
    private string? _errorMessage;
    private bool _isValidating;
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";
    private string? _emailError;

    // Step 2 state
    private List<WorkEntryModel> _workEntries = new() { new() };

    // Step 3 state
    private List<ReferenceModel> _references = new() { new(), new() };

    // Step 4 state
    private string _coverLetter = "";

    private void NavigateToStep(int step)
    {
        _errorMessage = null;
        _currentStep = step;
    }

    private void NextStep()
    {
        _errorMessage = null;
        _currentStep++;
    }

    private void PreviousStep()
    {
        _errorMessage = null;
        _currentStep--;
    }

    // Step 1 navigation
    private async Task NextFromPersonalInfo()
    {
        _errorMessage = null;
        _emailError = null;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
            || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        _isValidating = true;
        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(_email);
            if (!isValid)
            {
                _emailError = "Please enter a valid email address.";
                return;
            }
            NextStep();
        }
        finally
        {
            _isValidating = false;
        }
    }

    // Step 2 navigation
    private void NextFromWorkHistory()
    {
        _errorMessage = null;
        var hasEmpty = _workEntries.Any(e =>
            string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title));
        if (hasEmpty)
        {
            _errorMessage = "Please fill in company name and job title for all positions.";
            return;
        }
        NextStep();
    }

    // Step 3 navigation
    private void NextFromReferences()
    {
        _errorMessage = null;
        var hasEmpty = _references.Any(r =>
            string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email));
        if (hasEmpty)
        {
            _errorMessage = "Please fill in at least name and email for all references.";
            return;
        }
        NextStep();
    }

    // Work entry management
    private void AddWorkEntry() => _workEntries.Add(new());
    private void RemoveWorkEntry(int index) => _workEntries.RemoveAt(index);
    private void UpdateWorkEntry(int index, WorkEntryEditor.WorkEntryData data)
    {
        _workEntries[index] = new WorkEntryModel
        {
            Company = data.Company,
            Title = data.Title,
            StartDate = data.StartDate,
            EndDate = data.EndDate,
            IsCurrent = data.IsCurrent,
            Description = data.Description
        };
    }

    // Reference management
    private void AddReference() { if (_references.Count < 3) _references.Add(new()); }
    private void RemoveReference(int index) => _references.RemoveAt(index);
    private void UpdateReference(int index, ReferenceEditor.ReferenceData data)
    {
        _references[index] = new ReferenceModel
        {
            Name = data.Name,
            Relationship = data.Relationship,
            Email = data.Email,
            Phone = data.Phone
        };
    }

    // Submit
    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        try
        {
            var application = new JobApplication(
                new PersonalInfo(_fullName, _email, _phone, _address),
                new WorkHistory(_workEntries.Select(e =>
                    new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
                _references.Select(r =>
                    new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                _coverLetter
            );
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

