+            || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
+        {
+            _errorMessage = "Please fill in all required fields.";
+            return;
+        }
+
+        _isValidating = true;
+        try
+        {
+            var isValid = await ApplicationService.ValidateEmailAsync(_email);
+            if (!isValid)
+            {
+                _emailError = "Please enter a valid email address.";
+                return;
+            }
+            NextStep();
+        }
+        finally
+        {
+            _isValidating = false;
+        }
+    }
+
+    // Step 2 navigation
+    private void NextFromWorkHistory()
+    {
+        _errorMessage = null;
+        var hasEmpty = _workEntries.Any(e =>
+            string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title));
+        if (hasEmpty)
+        {
+            _errorMessage = "Please fill in company name and job title for all positions.";
+            return;
+        }
+        NextStep();
+    }
+
+    // Step 3 navigation
+    private void NextFromReferences()
+    {
+        _errorMessage = null;
+        var hasEmpty = _references.Any(r =>
+            string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email));
+        if (hasEmpty)
+        {
+            _errorMessage = "Please fill in at least name and email for all references.";
+            return;
+        }
+        NextStep();
+    }
+
+    // Work entry management
+    private void AddWorkEntry() => _workEntries.Add(new());
+    private void RemoveWorkEntry(int index) => _workEntries.RemoveAt(index);
+    private void UpdateWorkEntry(int index, WorkEntryEditor.WorkEntryData data)
+    {
+        _workEntries[index] = new WorkEntryModel
+        {
+            Company = data.Company,
+            Title = data.Title,
+            StartDate = data.StartDate,
+            EndDate = data.EndDate,
+            IsCurrent = data.IsCurrent,
+            Description = data.Description
+        };
+    }
+
+    // Reference management
+    private void AddReference() { if (_references.Count < 3) _references.Add(new()); }
+    private void RemoveReference(int index) => _references.RemoveAt(index);
+    private void UpdateReference(int index, ReferenceEditor.ReferenceData data)
