@namespace sv_feaa0fe75bf642d5a897e2dadda3a343.Components.Application

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h6 class="card-title mb-0">Position @Index</h6>
            @if (ShowRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name</label>
                <input type="text" class="form-control" value="@Company"
                       @onchange="CompanyChanged" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title</label>
                <input type="text" class="form-control" value="@Title"
                       @onchange="TitleChanged" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date</label>
                <input type="date" class="form-control" value="@StartDate.ToString("yyyy-MM-dd")"
                       @onchange="StartDateChanged" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@(EndDate?.ToString("yyyy-MM-dd"))"
                       disabled="@IsCurrent"
                       @onchange="EndDateChanged" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check">
                    <input class="form-check-input" type="checkbox" checked="@IsCurrent"
                           @onchange="IsCurrentChanged" />
                    <label class="form-check-label">Currently working here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" @onchange="DescriptionChanged">@Description</textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = string.Empty;
    [Parameter] public string Title { get; set; } = string.Empty;
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = string.Empty;
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);

    private void CompanyChanged(ChangeEventArgs e) { Company = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }
    private void TitleChanged(ChangeEventArgs e) { Title = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }
    private void StartDateChanged(ChangeEventArgs e) { StartDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : DateTime.Today; NotifyChanged(); }
    private void EndDateChanged(ChangeEventArgs e) { EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null; NotifyChanged(); }
    private void IsCurrentChanged(ChangeEventArgs e) { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; NotifyChanged(); }
    private void DescriptionChanged(ChangeEventArgs e) { Description = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, EndDate, IsCurrent, Description));
    }
}

